-- Reformer special (přání studia 25. 11. 2026): vlastní fotka (dvojice na reformerech, občerstvení, skripta a dárky) místo té
-- převzaté od Reformer fusion a v textu lekce nově i skripta a dárek. Text i fotka se změní jen tam, kde je studio mezitím
-- nepřepsalo v administraci. Opakované spuštění nic nezmění.

-- 1) Fotka jako nahraný obrázek (ukáže se hned).
INSERT INTO "media" ("id", "filename", "mime", "width", "height", "size", "data") VALUES
  ('fde98b04-b87a-47b2-9a33-acba37c05d5d', 'reformer-special.webp', 'image/webp', 1600, 900, 108604, decode('', 'base64'))
ON CONFLICT ("id") DO NOTHING;
--> statement-breakpoint
-- 2) …u lekce Reformer special místo fotky převzaté od Reformer fusion – jen dokud ji studio nevyměnilo za jinou.
UPDATE "class_types" SET "image_url" = '/media/fde98b04-b87a-47b2-9a33-acba37c05d5d.webp'
WHERE "id" = '907efc90-899b-47a0-906f-6e4b41357c27'
  AND ("image_url" IS NULL OR "image_url" = (SELECT r."image_url" FROM "class_types" r WHERE r."slug" = 'reformer-fusion'))
  AND EXISTS (SELECT 1 FROM "media" WHERE "id" = 'fde98b04-b87a-47b2-9a33-acba37c05d5d');
--> statement-breakpoint
-- 3) Text lekce: skripta, dárek a občerstvení – jen dokud je tam text z 0175.
UPDATE "class_types" SET "description" = $d$Reformer special je odpoledne, kdy zpomalíme a vyladíme techniku. Ukážeme si, proč každý pohyb děláme právě takhle, a doladíme ho na tvoje tělo – na dalších lekcích pak ucítíš, jak ti to jde líp. Cvičí se ve dvojicích na šesti strojích, takže přijď ideálně se svou parťačkou (nebo se spárujete u nás). Prozradíme ti taky, jak cvičit doma bez reformeru skoro jako na něm. Odneseš si tištěná skripta se cviky a malý dárek od nás 🎁 a mezi cvičením na tebe čeká občerstvení. Doporučujeme protiskluzové ponožky – když je nemáš, koupíš si je u nás na recepci. 🧦$d$
WHERE "id" = '907efc90-899b-47a0-906f-6e4b41357c27'
  AND "description" = $d$Reformer special je odpoledne, kdy zpomalíme a vyladíme techniku. Ukážeme si, proč každý pohyb děláme právě takhle, a doladíme ho na tvoje tělo – na dalších lekcích pak ucítíš, jak ti to jde líp. Cvičí se ve dvojicích na šesti strojích, takže přijď ideálně se svou parťačkou (nebo se spárujete u nás). Prozradíme ti taky, jak cvičit doma bez reformeru skoro jako na něm, a domů si odneseš tištěný návod. Mezi tím na tebe čeká malé občerstvení. Doporučujeme protiskluzové ponožky – když je nemáš, koupíš si je u nás na recepci. 🧦$d$;
--> statement-breakpoint
-- 4) Fotka je vytvořená pomocí AI – stejné označení (vodoznak chobotnice s „AI“) jako ostatní AI fotky.
UPDATE "settings" SET "value" = (SELECT jsonb_agg(x ORDER BY x) FROM (SELECT DISTINCT jsonb_array_elements_text("value" || '["/media/fde98b04-b87a-47b2-9a33-acba37c05d5d.webp"]'::jsonb) x) s)
WHERE "key" = 'aiImages' AND jsonb_typeof("value") = 'array' AND NOT "value" ? '/media/fde98b04-b87a-47b2-9a33-acba37c05d5d.webp';
